app.get('/api/external-status', async (_req, res, next) => {
  try {
    const response = await fetch('https://api.example.com/status', { signal: AbortSignal.timeout(3000) });
    if (!response.ok) return res.status(502).json({ error: 'Upstream service failed' });
    const data = await response.json();
    if (typeof data.status !== 'string') return res.status(502).json({ error: 'Unexpected upstream response' });
    res.json({ status: data.status });
  } catch (error) { next(error); }
});
